import * as React from "react";
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type ColumnFiltersState,
  type SortingState,
  type Table as TanstackTable,
  type VisibilityState,
} from "@tanstack/react-table";
import { ArrowDownUpIcon, ChevronLeftIcon, ChevronRightIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "./button";
import { IconButton } from "./icon-button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "./table";

/**
 * figma: Data Table — "Powerful table and datagrids built using TanStack Table."
 *
 * The Figma page composes the Table, Checkbox and DropdownMenu components, so
 * this is a thin, typed shell over TanStack Table that renders through those
 * same parts. Sorting, filtering, selection and pagination are wired; column
 * definitions stay yours.
 */
function DataTable<TData, TValue>({
  columns,
  data,
  className,
  emptyMessage = "No results.",
  children,
}: {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  className?: string;
  emptyMessage?: React.ReactNode;
  /** Render prop for a toolbar above the table — filters, column toggles. */
  children?: (table: TanstackTable<TData>) => React.ReactNode;
}) {
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([]);
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({});
  const [rowSelection, setRowSelection] = React.useState({});

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    state: { sorting, columnFilters, columnVisibility, rowSelection },
  });

  return (
    <div data-slot="data-table" className={cn("flex flex-col gap-4", className)}>
      {children?.(table)}
      <div className="rounded-xl border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {header.isPlaceholder
                      ? null
                      : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id} data-state={row.getIsSelected() ? "selected" : undefined}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-24 text-center text-muted-foreground">
                  {emptyMessage}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} />
    </div>
  );
}

/** A sortable column header. Use it as a column's `header`. */
function DataTableColumnHeader({
  column,
  title,
  className,
}: {
  column: { toggleSorting: (desc?: boolean) => void; getIsSorted: () => false | "asc" | "desc" };
  title: string;
  className?: string;
}) {
  return (
    <Button
      variant="ghost"
      size="xs"
      className={cn("-ms-2", className)}
      onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
    >
      {title}
      <ArrowDownUpIcon data-icon="inline-end" />
    </Button>
  );
}

function DataTablePagination<TData>({ table }: { table: TanstackTable<TData> }) {
  const selected = table.getFilteredSelectedRowModel().rows.length;
  const total = table.getFilteredRowModel().rows.length;
  return (
    <div data-slot="data-table-pagination" className="flex items-center justify-between gap-2">
      <div className="text-sm text-muted-foreground">
        {selected} of {total} row(s) selected.
      </div>
      <div className="flex items-center gap-1">
        <IconButton
          variant="outline"
          size="sm"
          aria-label="Previous page"
          disabled={!table.getCanPreviousPage()}
          onClick={() => table.previousPage()}
        >
          <ChevronLeftIcon className="rtl:rotate-180" />
        </IconButton>
        <IconButton
          variant="outline"
          size="sm"
          aria-label="Next page"
          disabled={!table.getCanNextPage()}
          onClick={() => table.nextPage()}
        >
          <ChevronRightIcon className="rtl:rotate-180" />
        </IconButton>
      </div>
    </div>
  );
}

export { DataTable, DataTableColumnHeader, DataTablePagination };
